last2 = sorted_orders[:2]
for i,o in enumerate(last2):
    print('--- last2', i, '---')
    keys = ['order_id','created_at','paid_amount','tax','delivery_fee','gift_wrap_fee','discount','address_text','payment_card_digits','order_items']
    for k in keys:
        if k in o:
            v=o[k]
            if k=='order_items':
                # print first item summary
                print('order_items_count', len(v))
                if v:
                    it=v[0]
                    print('first_item', {kk:it.get(kk) for kk in ['product_id','product_name','ordered_quantity','price']})
            else:
                print(k, v)
        else:
            print(k, 'MISSING')

paid_sum = sum(o.get('paid_amount',0.0) for o in last2)
print('paid_sum_last2', paid_sum)

from datetime import datetime

# Use amazon_orders fetched earlier
print('amazon_orders_available', 'amazon_orders' in globals())
orders = amazon_orders if 'amazon_orders' in globals() else []
print('orders_count', len(orders))

def parse_dt(s):
    try:
        return datetime.fromisoformat(s.replace('Z','+00:00'))
    except Exception as e:
        return None

sorted_orders = sorted(orders, key=lambda o: parse_dt(o.get('created_at')) or datetime.min, reverse=True)
last2 = sorted_orders[:2]
print('last2_order_ids', [o.get('order_id') for o in last2])

for idx,o in enumerate(last2):
    print('\nORDER', idx)
    for k in ['order_id','created_at','paid_amount','tax','delivery_fee','gift_wrap_fee','discount','address_text','payment_card_digits']:
